@Injectable()
export class FilterService {
  // }
  private readonly logger = new AppLogger();

  private readonly client: CosmosClient;

  private readonly database;

  private readonly container;

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly daprConfigService: DaprConfigService,
    private readonly cosmosDatabasebService: CosmosDatabaseService,
  ) {
    // Create DefaultAzureCredential with the user-assigned managed identity's Client ID
    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosDatabasebService.cosmosDbEndpoint,
    });

    this.database = this.client.database(
      this.cosmosDatabasebService.cosmosDbDatabase,
    );
    this.container = this.database.container(
      this.cosmosDatabasebService.cosmosDbContainer,
    );
    this.daprClient = new DaprClient();
  }

  public async getWorkCentersGroupedByUapsByPlant(plant: number): Promise<
    Array<{
      uapId: string;
      workcenters: Array<{ wcCode: string; wcDesc: string }>;
    }>
  > {
    try {
      // 1ï¸â£ Get hierarchy from API
      const response = await this.daprClient.invoker.invoke(
        this.daprConfigService.plantHierarchyApiAppId,
        `plant/getHierarchy/${plant}`,
        HttpMethod.GET,
      );

      const plantData = Array.isArray(response) ? response[0] : response;
      const uaps = plantData?.uaps || [];

      // 2ï¸â£ Group work centers by UAP
      const groupedMap: Record<
        string,
        Array<{ wcCode: string; wcDesc: string }>
      > = {};

      for (const uap of uaps) {
        const { uapId } = uap;
        groupedMap[uapId] = groupedMap[uapId] || [];

        const productionLines = uap.productionLines || [];
        for (const line of productionLines) {
          for (const wc of line.workcenters) {
            groupedMap[uapId].push({
              wcCode: wc.workcenterId,
              wcDesc: wc.workcenterDesc,
            });
          }
        }
      }

      // Transform to array format
      return Object.entries(groupedMap)
        .map(([uapId, workcenters]) => ({
          uapId,
          workcenters,
        }))
        .filter((item) => item.workcenters.length > 0);
    } catch (error) {
      this.logger.error('Failed to fetch work centers by plant', error);
      throw new Error('Could not fetch work centers');
    }
  }

  public async getWorkCentersByPlant(
    plant: number,
    filters: GetWorkCentersDto,
  ): Promise<Array<{ wcCode: string; wcDesc: string }>> {
    // Start constructing the SQL query
    let query = `
    SELECT DISTINCT c.wcCode, c.wcDesc FROM c
    WHERE c.plant = @plant
  `;

    const container = this.cosmosDatabasebService.getContainer;

    // Add filters to the query dynamically
    if (filters.outboundDelivery?.length) {
      const outboundDeliveryList = filters.outboundDelivery
        .map((delivery) => `'${delivery}'`)
        .join(', ');
      query += ` AND c.erpDelNo IN (${outboundDeliveryList})`;
    }
    if (filters.customer?.length) {
      const customerList = filters.customer
        .map((customer) => `'${customer}'`)
        .join(', ');
      query += ` AND c.customer IN (${customerList})`;
    }
    if (filters.pickingOrder?.length) {
      const pickingOrderList = filters.pickingOrder
        .map((order) => `'${order}'`)
        .join(', ');
      query += ` AND c.shopOrder IN (${pickingOrderList})`;
    }
    if (filters.material?.length) {
      const materialList = filters.material
        .map((material) => `'${material}'`)
        .join(', ');
      query += ` AND c.material IN (${materialList})`;
    }

    try {
      // Execute the query
      const { resources: workCenters } = await container.items
        .query({
          parameters: [{ name: '@plant', value: Number(plant) }],

          query,
        })
        .fetchAll();
      return (
        workCenters.map((workCenter: { wcCode: string; wcDesc: string }) => ({
          wcCode: workCenter.wcCode,
          wcDesc: workCenter.wcDesc,
        })) || []
      );
    } catch (error) {
      this.logger.error('Error querying work centers:', error);
      throw new Error('Could not fetch work centers');
    }
  }

