@ApiTags('aggrTime')
@Controller('order-api')
export class OrderController {
  public constructor(private readonly orderService: OrderService) {}

  @Get('plant-config-order/:plantCode')
  public async getPlantConfigOrder(
    @Param('plantCode') plantCode: string,
  ): Promise<PlantResponse> {
    const parsedPlantCode = Number.parseInt(plantCode, 10);

    if (Number.isNaN(parsedPlantCode)) {
      throw new NotFoundException('Invalid plant code');
    }
    const plantConfigOrder =
      await this.orderService.getPlantConfigOrder(parsedPlantCode);
