        return {
          aggrTimeLvlBoard: plantConfigOrder.aggrTimeLvlBoard,
          offsetFrom: plantConfigOrder.offsetFrom,
          offsetTo: plantConfigOrder.offsetTo,
          toleranceValueWk: plantConfigOrder.toleranceValueWk,
        };
      }

      return null;
