import { Injectable } from '@nestjs/common';
import { DateTime } from 'luxon';
import WkOrder from '../dto/wk-order-dto';
import { Item } from '../types/plant-hry-information';

type WkOrderGroup = Record<string, Array<WkOrder>> & {
  launcherWaitingTime?: string;
  minLauncherWaitingTime?: number;
  maxLauncherWaitingTime?: number;
};

@Injectable()
export class WkHelperData {
  public static getGroupingData(
    data: Array<WkOrder>,
    groupeOne: string,
    groupeTwo: string,
    timezone?: string,
  ): Record<string, WkOrderGroup> | undefined {
    const result: Record<string, WkOrderGroup> = {};

    for (const item of data) {
      const levelOneValue = this.computeValue(
        item as Item,
        groupeOne,
        timezone,
      );
      const levelTwoValue = this.computeValue(
        item as Item,
        groupeTwo,
        timezone,
      );
      if (
        typeof levelOneValue === 'string' &&
        typeof levelTwoValue === 'string'
      ) {
        result[levelOneValue] ??= {};
        result[levelOneValue][levelTwoValue] ??= [];
        result[levelOneValue][levelTwoValue].push(item);
      }
    }

    // Enhancement: Move launcherWaitingTime, minLauncherWaitingTime, maxLauncherWaitingTime to group level for shopOrder/shopOrder grouping
    if (groupeOne === 'shopOrder' && groupeTwo === 'shopOrder') {
      for (const groupKey of Object.keys(result)) {
        // Find the first WK in the first subgroup to extract the values
        const subGroups = result[groupKey];
        let firstWK: WkOrder | undefined;
        for (const subKey of Object.keys(subGroups)) {
          if (
            Array.isArray(subGroups[subKey]) &&
            subGroups[subKey].length > 0
          ) {
            // Use array destructuring
            const [first] = subGroups[subKey];
            firstWK = first;
            break;
          }
        }
        if (firstWK) {
          // Attach to the group
          subGroups.launcherWaitingTime = firstWK.launcherWaitingTime;
          subGroups.minLauncherWaitingTime = firstWK.minLauncherWaitingTime;
          subGroups.maxLauncherWaitingTime = firstWK.maxLauncherWaitingTime;
        }
        // Remove from all WKs in this group
        for (const subKey of Object.keys(subGroups)) {
          if (Array.isArray(subGroups[subKey])) {
            subGroups[subKey] = subGroups[subKey].map((wk: WkOrder) => {
              const {
                launcherWaitingTime,
                minLauncherWaitingTime,
                maxLauncherWaitingTime,
                ...rest
              } = wk;
              return rest as WkOrder;
            });
          }
        }
      }
    }

    const sortedResult: Record<string, WkOrderGroup> = {};
    const keys = Object.keys(result);
    const sortedKeys = this.sortKeys(keys);
    for (const key of sortedKeys) {
      sortedResult[key] = result[key];
    }
    return sortedResult;
  }

  private static sortKeys(keys: Array<string>): Array<string> {
    return keys.sort((a, b) => {
      if (a === 'POOL') return 1;
      if (b === 'POOL') return -1;
      return 0;
    });
  }

  private static computeValue(
    item: Item,
    level: string,
    timezone?: string,
  ): string | undefined {
    const value = item[level];
    if (level === 'truck' && item.truckDepartureTime) {
      // Concatenate customerDesc and formatted truckDepartureTime
      const formattedDeparture = DateTime.fromISO(item.truckDepartureTime)
        .setZone(timezone)
        .toFormat('yyyy-MM-dd HH:mm');
      return `${item.customerDesc ?? ''} ${formattedDeparture}`.trim();
    }
    let wcCodeWithDesc: string | undefined;
    if (item.wcCode && item.wcDesc) {
      wcCodeWithDesc = `${item.wcCode} ${item.wcDesc}`.trim();
    }

    if (level === 'shopOrder') {
      switch (item.sourceType) {
        case 'POOL': {
          return item.sourceType;
        }
        default: {
          return wcCodeWithDesc ?? item.wcCode;
        }
      }
    }

    return value?.trim() === '' ? ' ' : value;
  }
}

