@Injectable()
export class WkService {
  private static addFiltersForQueryParameters(
    queryParameters: WkQueryParameters,
    filterConditions: Array<string>,
    queryParamter: Array<{ name: string; value: string | number | boolean }>,
    plantId: string,
    timezone: string,
  ): void {
    // Processing other fields based on the fieldMapping
    for (const key of Object.keys(queryParameters)) {
      const frontendKey = key as keyof FieldMappingDTO; // Ensure type safety
      if (fieldMapping[frontendKey]) {
        const cosmosField = fieldMapping[frontendKey];
        const value = queryParameters[frontendKey];

        if (value) {
          let condition: string | null = null;
          let formattedValues: Array<string> = [];

          if (typeof value === 'string') {
            formattedValues = String(value)
              .split(',')
              .map((v) => `'${v.trim()}'`);
          } else if (Array.isArray(value)) {
            formattedValues = value.map((v) => `'${v}'`);
          }

          if (formattedValues.length === 1) {
            condition = `c.${cosmosField} = ${formattedValues[0]}`;
          } else if (formattedValues.length > 1) {
            condition = `c.${cosmosField} IN (${formattedValues.join(', ')})`;
          }

          if (condition) {
            filterConditions.push(condition);
          }
        }
      }
    }

    this.addDateFilters(
      queryParameters,
      filterConditions,
      queryParamter,
      timezone,
    );
  }

  private static addDateFilters(
    queryParameters: WkQueryParameters,
    filterConditions: Array<string>,
    queryParamter: Array<{ name: string; value: string | number | boolean }>,
    timezone: string, // Accept timezone as a parameter
  ): void {
    if (queryParameters.startDate && queryParameters.endDate) {
      const { startDate } = queryParameters;
      const { endDate } = queryParameters;
      const { closedWKs } = queryParameters;

      let condition = `((c.plannedStartDate >= @startDate AND c.plannedStartDate <= @endDate) or (c.newPromiseTime >= @startDate AND c.newPromiseTime <= @endDate))`;

      queryParamter.push(
        { name: '@startDate', value: startDate },
        { name: '@endDate', value: endDate },
      );

      if (
        queryParameters.startPreparationDate &&
        queryParameters.startPreparation
      ) {
        const startPreparationDate = new Date(
          queryParameters.startPreparationDate,
        );
        const startOfDay = convertToUTC(
          startPreparationDate.toISOString(),
          timezone,
        );
        const endOfDay = convertToUTC(
          new Date(
            startPreparationDate.setHours(23, 59, 59, 999),
          ).toISOString(),
          timezone,
        );

        queryParamter.push(
          {
            name: '@StartPreparationDate',
            value: startOfDay.toISOString(),
          },
          {
            name: '@EndPreparationDate',
            value: endOfDay.toISOString(),
          },
        );

        const startPreparation = queryParameters.startPreparation.toLowerCase();

        switch (startPreparation) {
          case 'specific': {
            condition += ` AND c.tpaBeginPreparation >= @StartPreparationDate AND c.tpaBeginPreparation <= @EndPreparationDate`;
            break;
          }
          case 'future': {
            condition += ` AND c.tpaBeginPreparation >= @StartPreparationDate`;
            break;
          }
          case 'past': {
            condition += ` AND c.tpaBeginPreparation <= @StartPreparationDate`;
            break;
          }
          default: {
            break;
          }
        }
      }

      if (
        queryParameters.truckDepartureDate &&
        queryParameters.truckDeparture
      ) {
        const truckDepartureDate = new Date(queryParameters.truckDepartureDate);
        const startOfDay = convertToUTC(
          truckDepartureDate.toISOString(),
          timezone,
        );
        const endOfDay = convertToUTC(
          new Date(truckDepartureDate.setHours(23, 59, 59, 999)).toISOString(),
          timezone,
        );

        queryParamter.push(
          {
            name: '@TruckDepartureDateStart',
            value: startOfDay.toISOString(),
          },
          {
            name: '@TruckDepartureDateEnd',
            value: endOfDay.toISOString(),
          },
        );

        const truckDeparture = queryParameters.truckDeparture.toLowerCase();

        switch (truckDeparture) {
          case 'specific': {
            condition += ` AND c.truckDepartureTime >= @TruckDepartureDateStart AND c.truckDepartureTime <= @TruckDepartureDateEnd`;
            break;
          }
          case 'future': {
            condition += ` AND c.truckDepartureTime >= @TruckDepartureDateStart`;
            break;
          }
          case 'past': {
            condition += ` AND c.truckDepartureTime <= @TruckDepartureDateStart`;
            break;
          }
          default: {
            break;
          }
        }
      }

      if (closedWKs?.toString().toLowerCase() === 'true') {
        const today = new Date();
        const sevenDaysAgo = new Date(today);
        sevenDaysAgo.setDate(today.getDate() - 7);

        const startDateISO = sevenDaysAgo.toISOString();
        const endDateISO = today.toISOString();

        // Include normal + recently closed/done
        condition += `
    AND (
      c.status NOT IN ('503', '504') 
      OR (
        c.status = '503' 
        AND c.plannedStartDate >= @sevenDaysAgo 
        AND c.plannedStartDate <= @today
      )
    )
  `;

        queryParamter.push(
          { name: '@sevenDaysAgo', value: startDateISO },
          { name: '@today', value: endDateISO },
        );
      } else {
        // Exclude CLOSED and DONE records completely
        condition += ` AND c.status NOT IN ('503', '504') `;
      }

      filterConditions.push(condition);
    }
  }

