  public async getWkOrderByCriteria(
    plantId: string,
    queryParameters: WkQueryParameters = {} as WkQueryParameters,
  ): Promise<plantResponse> {
    try {
      const plant = await this.getPlantById(Number(plantId));
      const timezone = plant.timezone ?? 'utc';

      const modifiedQueryParameters: WkQueryParameters = { ...queryParameters };
      // Handle pickingStatus and customStatus logic
      if (
        modifiedQueryParameters.pickingStatusList &&
        modifiedQueryParameters.pickingStatusList.length > 0 &&
        !modifiedQueryParameters.customStatusList
      ) {
        modifiedQueryParameters.customStatusList = [];
        for (const status of modifiedQueryParameters.pickingStatusList) {
          switch (status) {
            case 'IN PRODUCTION': {
              modifiedQueryParameters.customStatusList.push(
                'OPEN',
                'PIK_CREATED',
                'PIK_LAUNCHED',
                'PIK_IN_KITTING',
                'PIK_IN_PRODUCTION',
                'SFG_PIK_LAUNCHED',
                'SFG_PIK_KITTING',
                'SFG_PIK_PRODUCTION',
              );
              break;
            }
            case 'CLOSED': {
              modifiedQueryParameters.customStatusList.push(
                'PICKED',
                'PALLETIZED',
                'PIK_CLOSED',
              );
              break;
            }
            case 'TAKE FROM POOL': {
              modifiedQueryParameters.customStatusList.push('TAKE_FROM_STOCK');
              break;
            }
            default: {
              // No custom status for undefined picking statuses
              break;
            }
          }
        }
      }

      let filteredOrders: Array<wkOrder> = await this.getShopOrdersByPlant(
        Number(plantId),
        modifiedQueryParameters,
      );
      filteredOrders =
        await this.updateItemsColorAndConvertToTimeZone(filteredOrders);
      if (Array.isArray(filteredOrders)) {
        filteredOrders.sort((a, b) => {
          const dateA = new Date(a.plannedStartDate);
          const dateB = new Date(b.plannedStartDate);
          return dateA.getTime() - dateB.getTime(); // Ascending order
        });
      }
      let groupingData: unknown = [];

      groupingData =
        modifiedQueryParameters.filterGroupingOne &&
        modifiedQueryParameters.filterGroupingTwo
          ? WkHelperData.getGroupingData(
              filteredOrders,
              modifiedQueryParameters.filterGroupingOne,
              modifiedQueryParameters.filterGroupingTwo,
              timezone,
            )
          : filteredOrders;

      // Remove launcherWaitingTime fields from wkOrderList if not shopOrder/shopOrder grouping
      const isShopOrderGrouping =
        modifiedQueryParameters.filterGroupingOne === 'shopOrder' &&
        modifiedQueryParameters.filterGroupingTwo === 'shopOrder';
      if (!isShopOrderGrouping && Array.isArray(groupingData)) {
        groupingData = groupingData.map((wk: wkOrder) => {
          const {
            launcherWaitingTime,
            minLauncherWaitingTime,
            maxLauncherWaitingTime,
            ...rest
          } = wk;
          return rest;
        });
      }

      const combinedConfig = await this.orderService.getCombinedPlantConfig(
        Number(plantId),
      );

      let aggrTimeLvlBoard = 0;
      let toleranceValueWk = 0;

      if (combinedConfig) {
        const {
          aggrTimeLvlBoard: configAggrTimeLvlBoard,
          toleranceValueWk: configToleranceValueWk,
        } = combinedConfig;

        aggrTimeLvlBoard = configAggrTimeLvlBoard;
        toleranceValueWk = configToleranceValueWk;
      }
      return {
        aggrTimeLvlBoard,
        plantId,
        toleranceValueWk,
        wkOrderList: groupingData,
      } as plantResponse;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve WK orders for plantId ${plantId}`,
        error,
      );

      return {
        aggrTimeLvlBoard: 0,
        toleranceValueWk: 0,
        plantId,
        wkOrderList: [],
      } as plantResponse;
    }
  }

  public async getWkByPlantIdAndWkOrderId(
    plantId: string,
    pickingOrderId: string,
  ): Promise<WkOrderResponse> {
    try {
      const dataByPlant = await this.getWkOrderByCriteria(plantId);

      if (Object.keys(dataByPlant.wkOrderList).length === 0) {
        this.logger.warn(`No WK orders found for plantId ${plantId}`);
        return { plantId, wkOrderList: {} };
      }

      const arraydataByPlant: any = Object.values(dataByPlant);
      const pickingOrder = arraydataByPlant[1].find(
        (item: wkOrder) => item.pickingOrderId === pickingOrderId,
      );

      if (pickingOrder) {
        return { plantId, wkOrderList: pickingOrder };
      }

      this.logger.warn(
        `WK order with ID ${pickingOrderId} not found for plantId ${plantId}`,
      );
      throw new HttpException(
        `The WK order with the id ${pickingOrderId} does not exist`,
        404,
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve WK order with ID ${pickingOrderId} for plantId ${plantId}`,
        error,
      );
      throw new InternalServerErrorException('Error retrieving WK order');
    }
  }

  // Retrieve the list of shop orders by plant
  public async getShopOrdersByPlant(
    plant: number,
    queryParameters: WkQueryParameters,
  ): Promise<Array<wkOrder>> {
    try {
      const filterConditions: Array<string> = []; // Array of filter strings
      const queryParamter: Array<{
        name: string;
        value: string | number | boolean;
      }> = [];
      const plantDetails = await this.getPlantById(plant);
      const timezone = plantDetails.timezone ?? 'utc';
      WkService.addFiltersForQueryParameters(
        queryParameters,
        filterConditions,
        queryParamter,
        plant.toString(),
        timezone,
      );

      const queryParameterPlant = [{ name: '@plant', value: Number(plant) }]; // Base parameter for plant
      const allQueryParameters = [...queryParameterPlant, ...queryParamter];

      // Determine if we should exclude launcherWaitingTime fields
      const groupingOne = queryParameters.filterGroupingOne;
      const groupingTwo = queryParameters.filterGroupingTwo;
      const isShopOrderGrouping =
        groupingOne === 'shopOrder' && groupingTwo === 'shopOrder';

      const queryString = `SELECT * FROM c WHERE c.plant = @plant${
        filterConditions.length > 0
          ? ` AND ${filterConditions.join(' AND ')}`
          : ''
      }`;
      const { resources } = await this.cosmosDatabasebService.getContainer.items
        .query({
          parameters: allQueryParameters,
          query: queryString,
        })
        .fetchAll();
      if (resources.length === 0) {
        return [];
      }

      // Remove launcher-related fields if not shop order grouping
      if (!isShopOrderGrouping) {
        return resources.map((item: wkOrder) => {
          const {
            launcherWaitingTime,
            minLauncherWaitingTime,
            maxLauncherWaitingTime,
            ...rest
          } = item;
          return rest;
        });
      }

      // You can return only the shop orders or full documents
      return resources;
    } catch (error) {
      throw new Error(`Error fetching shop orders by plant : ${error}`);
    }
  }

  private async updateItemsColorAndConvertToTimeZone(
    filteredOrders: Array<wkOrder>,
    ghost: Record<string, string> | undefined = undefined,
  ): Promise<Array<wkOrder>> {
    const updatedOrders = await Promise.all(
      filteredOrders.map(async (item: wkOrder) => {
        const {
          pickingTime,
          plannedStartDate,
          truckDepartureTime,
          tpaEndPreparation,
          tpaBeginPreparation,
          customerDesc,
          destinationType,
        } = item;
        const updatedItem = { ...item };
        updatedItem.color = this.updateColorAttribute(item);
        if (pickingTime) {
          updatedItem.pickingTime = pickingTime;
        }
        updatedItem.ghost = ghost ? ghost[item.wcCode] : 'false';
        if (plannedStartDate) {
          updatedItem.plannedStartDate = plannedStartDate;
        }

        if (truckDepartureTime) {
          updatedItem.truckDepartureTime = truckDepartureTime;
        }

        if (tpaEndPreparation) {
          updatedItem.tpaEndPreparation = tpaEndPreparation;
        }

        if (tpaBeginPreparation) {
          updatedItem.tpaBeginPreparation = tpaBeginPreparation;
        }

        const truck = await WkService.getTruck(
          destinationType,
          customerDesc,
          updatedItem.truckDepartureTime,
        );

        updatedItem.truck = truck;

        return updatedItem;
      }),
    );

    return updatedOrders;
  }

  private updateColorAttribute(item: wkOrder): string {
    try {
      const currentDate = Date.now();
      if (item.truckDepartureTime && validateDate(item.truckDepartureTime)) {
        const truckDepartureTime = new Date(item.truckDepartureTime).getTime();
        if (
          typeof item.newPromiseTime === 'string' &&
          validateDate(item.newPromiseTime)
        ) {
          const newPromiseTime = new Date(item.newPromiseTime).getTime();
          if (newPromiseTime > truckDepartureTime) {
            return 'RED';
          }
        }
        if (currentDate > truckDepartureTime) {
          return 'RED';
        }
        const tpaEndPreparationCheck = tpaEndPreparationChecks(
          item,
          truckDepartureTime,
          currentDate,
        );
        if (tpaEndPreparationCheck) {
          return tpaEndPreparationCheck;
        }
      }
      if (item.pickingTime && validateDate(item.pickingTime)) {
        return whiteOrGreyCheck(item, currentDate);
      }
      return '';
    } catch (error) {
      this.logger.error(
        `error in updateColorAttribute  for plant ${item?.plant} and wk ${item?.shopOrder} `,
        error,
      );
      return '';
    }
  }

